#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-2d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
	B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Hoist constants (_PB_N, _PB_TSTEPS and SCALAR_VAL(0.2)) out of loops.
   - Use row pointers (Ai, Ai_prev, Ai_next, etc.) to reduce address
     arithmetic and improve cache locality.
   - Add OpenMP parallelism over the outer spatial dimension (i) and
     keep the time loop (t) sequential per thread, with implicit
     barriers between the two stencil sweeps in each time step.
   - Add OpenMP 'simd' to aid vectorization of the innermost loop.
   Semantics remain identical to the original Jacobi iteration.
*/
static void __attribute__((noinline))
kernel_jacobi_2d(int tsteps,
		 int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  /* Use the PolyBench loop bounds (they may depend on n/tsteps). */
  const int T_ = _PB_TSTEPS;
  const int N_ = _PB_N;

  /* Stencil scaling factor, hoisted out of all loops. */
  const DATA_TYPE c0 = SCALAR_VAL(0.2);

#pragma scop
  /* One parallel region to amortize threading overhead across all time steps.
     If OpenMP is not enabled at compile time, all '#pragma omp' directives
     are ignored and the code executes sequentially with the same semantics. */
#pragma omp parallel
  {
    int t, i, j;

    for (t = 0; t < T_; t++)
    {
      /* First sweep: compute B from A.
         Each (i,j) in the interior can be updated independently, so we
         parallelize over i and vectorize over j. */
#pragma omp for schedule(static)
      for (i = 1; i < N_ - 1; i++)
      {
        /* Row pointers to improve locality and reduce index arithmetic. */
        DATA_TYPE *restrict Bi      = B[i];
        DATA_TYPE *restrict Ai      = A[i];
        DATA_TYPE *restrict Ai_prev = A[i-1];
        DATA_TYPE *restrict Ai_next = A[i+1];

        /* No loop-carried dependencies in j: safe to vectorize. */
#pragma omp simd
        for (j = 1; j < N_ - 1; j++)
        {
          Bi[j] = c0 * ( Ai[j]      +
                         Ai[j-1]    +
                         Ai[j+1]    +
                         Ai_prev[j] +
                         Ai_next[j] );
        }
      }
      /* Implicit barrier here at the end of 'omp for':
         guarantees that the whole B has been updated before A is read. */

      /* Second sweep: compute A from B, same pattern as above. */
#pragma omp for schedule(static)
      for (i = 1; i < N_ - 1; i++)
      {
        DATA_TYPE *restrict Ai      = A[i];
        DATA_TYPE *restrict Bi      = B[i];
        DATA_TYPE *restrict Bi_prev = B[i-1];
        DATA_TYPE *restrict Bi_next = B[i+1];

#pragma omp simd
        for (j = 1; j < N_ - 1; j++)
        {
          Ai[j] = c0 * ( Bi[j]      +
                         Bi[j-1]    +
                         Bi[j+1]    +
                         Bi_prev[j] +
                         Bi_next[j] );
        }
      }
      /* Implicit barrier at end of this 'omp for' ensures that all updates
         to A at time step t are complete before proceeding to t+1. */
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
