    {
      /* First sweep: update B based on the current values of A. */
#if defined(_OPENMP)
#pragma omp for schedule(static)
#endif
      for (i = 1; i < _PB_N - 1; i++)
	{
	  /* Cache frequently used row pointers to improve locality and
	     reduce address arithmetic inside the inner loop. */
	  DATA_TYPE *Bi   = B_[i];
	  DATA_TYPE *Ai   = A_[i];
	  DATA_TYPE *Aim1 = A_[i-1];
	  DATA_TYPE *Aip1 = A_[i+1];

#if defined(__GNUC__)
#pragma GCC ivdep
#endif
	  for (j = 1; j < _PB_N - 1; j++)
	    Bi[j] = c0 * (Ai[j]     +
			  Ai[j-1]   +
			  Ai[j+1]   +
			  Aim1[j]   +
			  Aip1[j]);
	}

      /* Second sweep: update A based on the new values of B. */
#if defined(_OPENMP)
#pragma omp for schedule(static)
#endif
      for (i = 1; i < _PB_N - 1; i++)
	{
	  DATA_TYPE *Ai   = A_[i];
	  DATA_TYPE *Bi   = B_[i];
	  DATA_TYPE *Bim1 = B_[i-1];
	  DATA_TYPE *Bip1 = B_[i+1];

#if defined(__GNUC__)
#pragma GCC ivdep
#endif
	  for (j = 1; j < _PB_N - 1; j++)
	    Ai[j] = c0 * (Bi[j]     +
			  Bi[j-1]   +
			  Bi[j+1]   +
			  Bim1[j]   +
			  Bip1[j]);
	}
    }

#if defined(_OPENMP)
  } /* end parallel */
#endif
#pragma endscop

}


