#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-2d.h"

/* Tunable blocking factor for the inner (j) dimension.
   Can be changed at compile time to better match a given cache
   hierarchy (must be > 0). */
#ifndef JACOBI_2D_J_BLOCK
# define JACOBI_2D_J_BLOCK 64
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  /* Use restrict-qualified local pointers to help the compiler
     optimize memory accesses.  The PolyBench allocation guarantees
     that A and B are distinct arrays. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  /* Parallel initialization (when compiled with OpenMP) is outside
     the timed region in main(), so it does not affect the measured
     kernel performance but warms up the OpenMP runtime. */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      {
	A_[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
	B_[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  /* n is the full allocated size; _PB_N is the (possibly reduced)
     effective loop bound used by PolyBench.  Use n for the array
     shape and _PB_N for loop limits to preserve original semantics
     even if PolyBench changes the loop bounds. */
  const int n_full     = n;
  const int n_eff      = _PB_N;
  const int tsteps_eff = _PB_TSTEPS;

  /* Local restrict-qualified views of the 2D arrays.
     A and B are distinct PolyBench allocations, so it is safe to
     assume they do not alias. */
  DATA_TYPE (*restrict A_)[n_full] = A;
  DATA_TYPE (*restrict B_)[n_full] = B;

  /* Constant factor of the Jacobi stencil. Hoisted out of the loops
     to avoid repeated SCALAR_VAL() expansion. */
  const DATA_TYPE c = SCALAR_VAL(0.2);

  /* Precompute loop bounds to avoid repeated arithmetic. */
  const int i_start = 1;
  const int i_end   = n_eff - 1; /* exclusive upper bound: [1, n_eff-2] */
  const int j_start = 1;
  const int j_end   = n_eff - 1; /* exclusive upper bound: [1, n_eff-2] */
  const int j_block = JACOBI_2D_J_BLOCK;

#pragma scop
  /* Use a single OpenMP parallel region to amortize start-up costs.
     The outer time loop remains sequential; the spatial loops are
     parallelized.  When compiled without OpenMP support, these
     pragmas are ignored and the code executes sequentially. */
#pragma omp parallel
  {
    for (int t = 0; t < tsteps_eff; t++)
    {
      /* First sweep: compute B from A. */
#pragma omp for schedule(static)
      for (int i = i_start; i < i_end; i++)
      {
        /* Cache row pointers to reduce address arithmetic in the
           innermost loop and to improve cache locality.  Each row is
           a distinct, non-overlapping subobject, so these pointers
           can safely be marked restrict. */
        DATA_TYPE *restrict Bi      = B_[i];
        DATA_TYPE *restrict Ai      = A_[i];
        DATA_TYPE *restrict Ai_prev = A_[i-1];
        DATA_TYPE *restrict Ai_next = A_[i+1];

        /* Block the j-dimension so that each block operates on a
           small horizontal stripe that fits well in L1 cache. */
        for (int jj = j_start; jj < j_end; jj += j_block)
        {
          const int j_max = (jj + j_block < j_end) ? (jj + j_block) : j_end;

          /* The stencil has no loop-carried dependencies in j, so
             this loop can be vectorized.  With OpenMP, this becomes
             an explicit SIMD loop; otherwise the pragma is ignored
             and the compiler may still auto-vectorize. */
#pragma omp simd
          for (int j = jj; j < j_max; j++)
          {
            Bi[j] = c * (Ai[j] + Ai[j-1] + Ai[j+1]
                           + Ai_prev[j] + Ai_next[j]);
          }
        }
      }

      /* Implicit barrier here: all threads have finished updating B
         before any thread starts updating A. */

      /* Second sweep: compute A from B. */
#pragma omp for schedule(static)
      for (int i = i_start; i < i_end; i++)
      {
        DATA_TYPE *restrict Ai      = A_[i];
        DATA_TYPE *restrict Bi      = B_[i];
        DATA_TYPE *restrict Bi_prev = B_[i-1];
        DATA_TYPE *restrict Bi_next = B_[i+1];

        for (int jj = j_start; jj < j_end; jj += j_block)
        {
          const int j_max = (jj + j_block < j_end) ? (jj + j_block) : j_end;

#pragma omp simd
          for (int j = jj; j < j_max; j++)
          {
            Ai[j] = c * (Bi[j] + Bi[j-1] + Bi[j+1]
                           + Bi_prev[j] + Bi_next[j]);
          }
        }
      }

      /* Implicit barrier here: all threads finish updating A for this
         time step before proceeding to the next t. */
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
