/* Array initialization.
 *
 * Optimizations:
 *  - Hoist the cast of `n` to DATA_TYPE out of the loops.
 *  - Parallelize the 2D loop with OpenMP and use a static schedule.
 *    Each (i,j) iteration is independent, so this is safe.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  const DATA_TYPE fn = (DATA_TYPE)n;

  /* Both loops are perfectly parallel and have no dependencies. */
#pragma omp parallel for schedule(static) collapse(2)
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      {
	A[i][j] = ((DATA_TYPE) i * (j + 2) + SCALAR_VAL(2.0)) / fn;
	B[i][j] = ((DATA_TYPE) i * (j + 3) + SCALAR_VAL(3.0)) / fn;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Introduce a single OpenMP parallel region around all time steps
 *    to reduce parallel-region creation overhead.
 *  - Parallelize the spatial loops with `#pragma omp for`.
 *  - Use row pointers (Ai, Aim1, Aip1, etc.) to improve cache locality
 *    and give the compiler simple, stride-1 memory accesses.
 *  - Declare these row pointers as `restrict` because rows are
 *    non-overlapping; this enables better vectorization.
 *  - Add `#pragma omp simd` on the inner j-loops to explicitly request
 *    SIMD vectorization where it is safe (no cross-iteration deps).
 *
 * The algorithm and update order are unchanged:
 *  - For each time step t:
 *      1) compute B from A (using only A from time t),
 *      2) compute A from B (using only B from the same time step).
 */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  const DATA_TYPE factor = SCALAR_VAL(0.2);

#pragma scop
  /* One parallel region for all time steps: lower overhead. */
#pragma omp parallel
  {
    for (int t = 0; t < _PB_TSTEPS; t++)
    {
      /* First sweep: B = stencil(A).  Each (i,j) is independent. */
#pragma omp for schedule(static)
      for (int i = 1; i < _PB_N - 1; i++)
      {
        /* Row pointers to improve locality and enable vectorization. */
        DATA_TYPE *restrict Bi   = B[i];
        DATA_TYPE *restrict Ai   = A[i];
        DATA_TYPE *restrict Aim1 = A[i-1];
        DATA_TYPE *restrict Aip1 = A[i+1];

        /* Safe to SIMD-vectorize over j: no loop-carried deps. */
#pragma omp simd
        for (int j = 1; j < _PB_N - 1; j++)
        {
          Bi[j] = factor * (Ai[j]     +
                            Ai[j-1]   +
                            Ai[j+1]   +
                            Aip1[j]   +
                            Aim1[j]);
        }
      }
      /* Implicit barrier here: all B values are ready. */

      /* Second sweep: A = stencil(B). */
#pragma omp for schedule(static)
      for (int i = 1; i < _PB_N - 1; i++)
      {
        DATA_TYPE *restrict Ai   = A[i];
        DATA_TYPE *restrict Bi   = B[i];
        DATA_TYPE *restrict Bim1 = B[i-1];
        DATA_TYPE *restrict Bip1 = B[i+1];

#pragma omp simd
        for (int j = 1; j < _PB_N - 1; j++)
        {
          Ai[j] = factor * (Bi[j]     +
                            Bi[j-1]   +
                            Bi[j+1]   +
                            Bip1[j]   +
                            Bim1[j]);
        }
      }
      /* Implicit barrier here: all A values are ready for next t. */
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

