/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Introduce a single OpenMP parallel region around the time loop
     so threads are created only once.
   - Use OpenMP 'for' worksharing on the spatial dimension 'i' for
     both Jacobi sweeps at each time step.
   - Create row pointers (with 'restrict') inside the inner loops to
     reduce address arithmetic and help the compiler with alias
     analysis.
   - Add GCC vectorization hints (#pragma GCC ivdep) on the innermost
     'j' loops to force vectorization under the assumption of no
     loop-carried dependencies (which holds for this standard Jacobi
     stencil).
   - Hoist SCALAR_VAL(0.2) into a local constant to avoid
     recomputation.
 */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  /* PolyBench provides the effective bounds via these macros.
   * They may depend on the runtime 'n' and 'tsteps', so we keep
   * using them, but store them in local constants for clarity.
   */
  const int tstepsPB = _PB_TSTEPS;
  const int nPB      = _PB_N;

  /* Constant factor used in the stencil. */
  const DATA_TYPE c0 = SCALAR_VAL(0.2);

  (void)tsteps; /* parameters kept for API compatibility */
  (void)n;

#pragma scop
  /* Single parallel region: avoids per-time-step thread creation. */
#pragma omp parallel
  {
    for (int t = 0; t < tstepsPB; ++t)
    {
      /* -------------------------------------------------------- */
      /* First sweep: B = stencil(A)                             */
      /* Each (i,j) update is independent, so we can parallelize  */
      /* over 'i' and vectorize over 'j'.                        */
      /* -------------------------------------------------------- */
#pragma omp for schedule(static)
      for (int i = 1; i < nPB - 1; ++i)
      {
        /* Row pointers improve locality and reduce indexing cost.
         * 'restrict' expresses that these pointers do not alias
         * with each other, enabling better optimization.
         */
        DATA_TYPE       *restrict Bi   = &B[i][0];
        const DATA_TYPE *restrict Ai   = &A[i][0];
        const DATA_TYPE *restrict Aim1 = &A[i-1][0];
        const DATA_TYPE *restrict Aip1 = &A[i+1][0];

        /* The GCC ivdep pragma tells the compiler there are no
         * loop-carried dependencies preventing vectorization.
         */
#pragma GCC ivdep
        for (int j = 1; j < nPB - 1; ++j)
        {
          Bi[j] = c0 * (Ai[j]     +
                        Ai[j-1]   +
                        Ai[j+1]   +
                        Aim1[j]   +
                        Aip1[j]);
        }
      }

      /* Implicit barrier at the end of 'omp for' ensures all
       * B[i][j] are computed before the next sweep uses them.
       */

      /* -------------------------------------------------------- */
      /* Second sweep: A = stencil(B)                            */
      /* Symmetric to the first sweep, but reading from B.       */
      /* -------------------------------------------------------- */
#pragma omp for schedule(static)
      for (int i = 1; i < nPB - 1; ++i)
      {
        const DATA_TYPE *restrict Bi   = &B[i][0];
        const DATA_TYPE *restrict Bim1 = &B[i-1][0];
        const DATA_TYPE *restrict Bip1 = &B[i+1][0];
        DATA_TYPE       *restrict Ai   = &A[i][0];

#pragma GCC ivdep
        for (int j = 1; j < nPB - 1; ++j)
        {
          Ai[j] = c0 * (Bi[j]     +
                        Bi[j-1]   +
                        Bi[j+1]   +
                        Bim1[j]   +
                        Bip1[j]);
        }
      }
      /* Implicit barrier here ensures all A[i][j] are updated
       * before proceeding to the next time step.
       */
    }
  }
#pragma endscop

}


